int longestConsecutive(vector<int>& nums) {
    unordered_set<int> s(nums.begin(), nums.end());
    int longest = 0;
    for(int num : s) {
        if(!s.count(num - 1)) {
            int cur = num, streak = 1;
            while(s.count(cur + 1)) { cur++; streak++; }
            longest = max(longest, streak);
        }
    }
    return longest;
}

